<template><el-dialog :model-value="modelValue" :title="t('users.temporaryPassword')" width="min(480px, 92vw)" destroy-on-close @closed="close"><el-alert :title="t('users.passwordWarning')" type="warning" :closable="false" show-icon/><div class="secret"><code>{{ password }}</code><el-button @click="copy">{{ t('users.copy') }}</el-button></div><template #footer><el-button type="primary" @click="close">{{ t('users.done') }}</el-button></template></el-dialog></template>
<script setup lang="ts">import { ElMessage } from 'element-plus'; import { useI18n } from 'vue-i18n'; const props=defineProps<{modelValue:boolean;password:string}>(); const emit=defineEmits<{(e:'update:modelValue',value:boolean):void;(e:'clear'):void}>(); const {t}=useI18n(); function close(){emit('update:modelValue',false);emit('clear')} async function copy(){await navigator.clipboard.writeText(props.password);ElMessage.success(t('users.copied'))}</script>
<style scoped>.secret{display:flex;gap:12px;align-items:center;margin-top:18px}.secret code{flex:1;overflow-wrap:anywhere;padding:12px;border:1px solid var(--tm-border);border-radius:6px;background:#f7f9fc;font:600 14px ui-monospace,SFMono-Regular,monospace}</style>
